<style>
:root{--studio-bg:#f5f5fa;--studio-card:#fff;--studio-text:#25243b;--studio-muted:#77768c;--studio-line:#eae9f1;--studio-accent:#7454da;--studio-soft:#f1edfc;--studio-shadow:0 4px 24px #29234304}
.dark{--studio-bg:#12131e;--studio-card:#1d1e2d;--studio-text:#edeefa;--studio-muted:#a8a9c1;--studio-line:#303145;--studio-soft:#302646;--studio-shadow:none}
body.fi-body{background:var(--studio-bg);color:var(--studio-text);font-family:Tajawal,Arial,sans-serif}
.fi-sidebar{background:#211f36;border:0;color:#bcb8d2}
.fi-sidebar-header{background:#211f36!important;border-bottom:1px solid #ffffff0c;height:84px}
.studio-brand{display:inline-flex;align-items:center;gap:12px;text-align:left;color:var(--studio-text);font-family:Arial,sans-serif;font-size:22px;font-weight:800;letter-spacing:1px;line-height:1.1}
.studio-brand small{display:block;font-size:8px;font-weight:500;letter-spacing:3px;margin-top:6px;color:var(--studio-muted)}
.studio-brand-mark{display:grid;place-items:center;background:#815de8;color:white;border-radius:12px;width:40px;height:40px;box-shadow:0 5px 16px #825fe83a}.studio-brand-mark svg{width:23px;height:23px}
.fi-sidebar .studio-brand{color:white}.fi-sidebar .studio-brand small{color:#aaa3c6}
.fi-sidebar-nav{padding:28px 18px;gap:28px}.fi-sidebar-group-label{color:#a8a1bd!important;font-size:11px;letter-spacing:.04em;font-weight:400!important}
.fi-sidebar-item-btn{min-height:46px;border-radius:10px!important;padding-inline:13px!important;transition:background .15s ease}
.fi-sidebar-item-label{color:#cdc9de!important;font-weight:500!important;font-size:14px}.fi-sidebar-item-icon{color:#aaa1c5!important;width:20px;height:20px}
.fi-sidebar-item-btn:hover{background:#ffffff08!important}.fi-sidebar-item.fi-active .fi-sidebar-item-btn{background:#8060d9!important;box-shadow:0 5px 16px #100b2c28}
.fi-sidebar-item.fi-active .fi-sidebar-item-label,.fi-sidebar-item.fi-active .fi-sidebar-item-icon{color:#fff!important}
.studio-sidebar-footer{display:flex;align-items:center;gap:12px;padding:20px;margin:16px;border-top:1px solid #ffffff10}.studio-sidebar-footer strong{display:block;color:#ddd9eb;font-size:12px}.studio-sidebar-footer span:not(.studio-footer-mark){display:block;font-size:11px;margin-top:3px;color:#9890b3}.studio-footer-mark svg{width:25px;color:#9d89d4}
.fi-topbar{background:var(--studio-card)!important;box-shadow:none!important;border-bottom:1px solid var(--studio-line);height:72px}.fi-topbar nav{height:72px}
.fi-main{padding-inline:32px!important}.fi-page{gap:24px;padding-block:28px}
.fi-header-heading{color:var(--studio-text);font-size:27px;font-weight:700;letter-spacing:-.4px}.fi-breadcrumbs{font-size:12px;color:var(--studio-muted)}
.studio-context{display:flex;justify-content:space-between;align-items:center;color:var(--studio-muted);font-size:12px;padding-bottom:18px;border-bottom:1px solid var(--studio-line);margin-bottom:20px}
.fi-section,.fi-ta-ctn,.fi-wi-stats-overview-stat{background:var(--studio-card)!important;border:1px solid var(--studio-line)!important;border-radius:16px!important;box-shadow:var(--studio-shadow)!important}
.fi-section-header{padding:22px 24px;border-bottom:1px solid var(--studio-line)}.fi-section-header-heading{font-size:16px!important;color:var(--studio-text)}.fi-section-content{padding:24px!important}
.fi-fo-field-label{font-size:13px!important;color:var(--studio-text)}.fi-fo-field-wrp-helper-text{font-size:12px;color:var(--studio-muted)}
.fi-input-wrp{border:1px solid var(--studio-line)!important;border-radius:9px!important;box-shadow:none!important;background:var(--studio-card)!important;min-height:42px}.fi-input-wrp:focus-within{border-color:#977be3!important;box-shadow:0 0 0 3px #8b6cd51a!important}.fi-input{font-size:14px!important}
.fi-btn{border-radius:9px!important;font-weight:700!important;min-height:39px;box-shadow:none!important;transition:transform .15s ease,filter .15s ease}.fi-btn:hover{filter:brightness(.97)}
.fi-ta-header-toolbar{padding:20px!important;border-bottom:1px solid var(--studio-line)}.fi-ta-header-cell{background:var(--studio-bg)!important;color:var(--studio-muted);padding-block:15px!important;font-size:12px!important;font-weight:600!important}.fi-ta-cell{padding-block:17px!important;border-color:var(--studio-line)}
.fi-ta-row{background:var(--studio-card)!important}.fi-ta-row:hover{background:var(--studio-soft)!important}.fi-ta-content{border-top:0!important}.fi-ta-ctn .fi-pagination{padding:18px 22px;border-top:1px solid var(--studio-line)}
.fi-badge{border-radius:6px!important;font-size:11px!important;font-weight:600!important;padding:5px 9px!important}.fi-tabs{border-radius:11px!important;box-shadow:none!important;border:1px solid var(--studio-line);background:var(--studio-card)!important;padding:5px}.fi-tabs-item{border-radius:7px!important}
.fi-modal-window,.fi-dropdown-panel,.fi-notification{border:1px solid var(--studio-line)!important;border-radius:16px!important;background:var(--studio-card)!important;box-shadow:0 20px 70px #17112920!important}.fi-modal-header{border-bottom:1px solid var(--studio-line);padding-bottom:20px!important}
.studio-dashboard{display:grid;gap:24px}.studio-eyebrow{font-size:11px;font-weight:700;letter-spacing:.04em;color:var(--studio-muted)}
.studio-welcome{display:flex;align-items:center;justify-content:space-between;gap:32px;background:linear-gradient(110deg,#eee8fc,#f5f2ff 60%,#eae5f8);border:1px solid #e6def6;border-radius:18px;padding:30px 36px;overflow:hidden;position:relative;min-height:215px}
.dark .studio-welcome{background:linear-gradient(110deg,#2c2344,#252135);border-color:#3d3154}.studio-welcome h2{font-size:30px;color:var(--studio-text);font-weight:700;margin:10px 0 8px;line-height:1.3}.studio-welcome p{color:var(--studio-muted);font-size:14px;line-height:1.8;max-width:570px}.studio-eyebrow span{padding:0 10px;color:#a4a0b2}
.studio-welcome-actions{display:flex;gap:22px;align-items:center;margin-top:22px}.studio-button{display:inline-flex;align-items:center;justify-content:center;gap:25px;color:white;background:#7454da;border:1px solid #7454da;padding:11px 18px;border-radius:8px;font-size:13px;font-weight:700;transition:background .15s}.studio-button:hover{background:#6240c8}.studio-text-link{color:#7754cc;font-size:12px;font-weight:700;text-decoration:none}.dark .studio-text-link{color:#bea6fa}.studio-text-link:hover{text-decoration:underline}
.studio-orbit{position:relative;flex-shrink:0;width:175px;height:175px;display:grid;place-items:center;border:1px dashed #b6a4de80;border-radius:50%;margin-inline:20px}.studio-orbit:after{content:'';position:absolute;inset:18px;border:1px solid #bdade33d;border-radius:50%}.studio-orbit-inner{width:112px;height:112px;background:#e0d6f7;border:8px solid #f1ebfc;border-radius:28px;color:#805cce;display:grid;place-items:center;transform:rotate(-8deg);box-shadow:0 12px 30px #8a6ec51a}.studio-orbit svg{width:74px}.studio-orbit-dot{position:absolute;top:15px;right:20px;background:#baa5e6;border:5px solid #f5effe;width:24px;height:24px;border-radius:50%}
.studio-metrics{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:18px}.studio-metric{padding:21px 23px;border:1px solid var(--studio-line);border-radius:14px;background:var(--studio-card);box-shadow:var(--studio-shadow)}.studio-metric-top{display:flex;align-items:center;justify-content:space-between;gap:10px;font-size:13px;color:var(--studio-muted)}.studio-metric strong{display:block;font-size:36px;line-height:1.25;margin:12px 0 7px;font-weight:700;font-variant-numeric:tabular-nums;color:var(--studio-text)}.studio-metric small{color:var(--studio-muted);font-size:11px}
.studio-icon{display:inline-flex;align-items:center;justify-content:center;width:36px;height:36px;border-radius:10px;flex-shrink:0}.studio-icon svg{width:19px;height:19px}.studio-icon.violet{background:#f0eafb;color:#8254d4}.studio-icon.green{background:#e8f6f0;color:#349676}.studio-icon.amber{background:#fff4df;color:#c28b32}.studio-icon.rose{background:#ffedf1;color:#cd6d87}
.studio-grid{display:grid;grid-template-columns:minmax(0,1.6fr) minmax(0,1fr);gap:22px}.studio-card{min-width:0;background:var(--studio-card);border:1px solid var(--studio-line);border-radius:15px;overflow:hidden;box-shadow:var(--studio-shadow)}.studio-card-heading{display:flex;align-items:center;justify-content:space-between;gap:16px;padding:23px 24px 19px}.studio-card-heading h3{font-size:17px;font-weight:700;color:var(--studio-text);margin-top:5px}.studio-subtle{font-size:11px;color:var(--studio-muted)}
.studio-table-scroll{overflow:auto}.studio-table{border-collapse:collapse;width:100%;font-size:12px;white-space:nowrap;text-align:start}.studio-table th{text-align:start;color:var(--studio-muted);font-weight:400;background:var(--studio-bg);padding:13px 20px}.studio-table td{padding:16px 20px;border-bottom:1px solid var(--studio-line);color:var(--studio-muted)}.studio-table tr:last-child td{border-bottom:0}.studio-device-cell{display:flex;align-items:center;gap:12px}.studio-device-cell a,.studio-device-cell div>span{font-weight:700;color:var(--studio-text);font-size:13px}.studio-device-cell a:hover{color:var(--studio-accent)}.studio-device-cell small{display:block;font-size:10px;margin-top:5px}.studio-device-icon{display:grid;place-items:center;background:var(--studio-bg);width:36px;height:36px;border-radius:9px;color:#8d87a2}.studio-device-icon svg{width:19px}.studio-method{padding:4px 9px;background:var(--studio-bg);border:1px solid var(--studio-line);border-radius:5px;color:var(--studio-muted);font-size:10px}.studio-pill{font-size:10px;border-radius:5px;padding:5px 8px}.studio-pill.approved{background:#e9f6ef;color:#35875b}.studio-pill.pending{background:#fff4dc;color:#9b7226}.studio-pill.blocked,.studio-pill.rejected{background:#fdebf0;color:#b05270}
.studio-methods{padding:3px 24px 16px}.studio-method-row{margin:15px 0}.studio-method-row>div:first-child{display:flex;justify-content:space-between;font-size:12px;color:var(--studio-text)}.studio-method-row span{display:inline-flex;align-items:center;gap:9px}.studio-method-row small{display:block;text-align:end;color:var(--studio-muted);font-size:10px;margin-top:5px}.studio-dot{width:8px;height:8px;border-radius:3px}.studio-track{height:7px;background:var(--studio-bg);border-radius:6px;overflow:hidden;margin-top:12px}.studio-track span{display:block;height:100%;border-radius:6px}.studio-dot.violet,.studio-track .violet{background:#9a7cde}.studio-dot.green,.studio-track .green{background:#60b7a0}.studio-dot.amber,.studio-track .amber{background:#e9b770}.studio-card-note{font-size:11px;line-height:1.7;color:var(--studio-muted);background:var(--studio-bg);padding:15px 24px;border-top:1px solid var(--studio-line)}
.studio-count{border-radius:7px;background:var(--studio-soft);color:var(--studio-accent);padding:4px 10px;font-size:12px}.studio-list{padding:0 24px 20px}.studio-list-row{display:flex;align-items:center;gap:12px;padding:14px 0;border-bottom:1px solid var(--studio-line)}.studio-list-row:last-child{border:0}.studio-list-row>div{flex:1;min-width:0}.studio-list-row strong{font-size:12px;color:var(--studio-text);overflow-wrap:anywhere}.studio-list-row small{display:block;font-size:10px;color:var(--studio-muted);margin-top:5px}.studio-mini-link{border:1px solid var(--studio-line);padding:6px 12px;border-radius:6px;color:var(--studio-accent);font-size:11px}
.studio-timeline{padding:0 24px 20px}.studio-event{display:flex;align-items:start;gap:13px;padding:14px 0;position:relative}.studio-event>i{height:8px;width:8px;border-radius:50%;background:#b39bdc;margin-top:6px;flex-shrink:0}.studio-event:not(:last-child):after{position:absolute;content:'';inset-inline-start:3px;top:30px;bottom:-8px;width:1px;background:var(--studio-line)}.studio-event div{flex:1}.studio-event strong{display:block;font-size:12px;font-weight:600}.studio-event div span,.studio-event time{font-size:10px;color:var(--studio-muted)}.studio-event div span{display:block;margin-top:5px}.studio-empty{text-align:center;padding:28px 16px;color:var(--studio-muted);white-space:normal}.studio-empty svg{width:34px;height:34px;margin:0 auto 12px;color:#b2a2cd}.studio-empty strong{font-size:13px;display:block;color:var(--studio-text)}.studio-empty p{font-size:11px;margin-top:7px;line-height:1.7}
.studio-page-footer{display:flex;justify-content:space-between;font-size:11px;color:var(--studio-muted);padding:0 3px 8px}
.fi-simple-layout{background:var(--studio-bg)}.fi-simple-main-ctn{padding:40px 24px!important}.fi-simple-main{max-width:1000px!important;width:100%;padding:52px!important;border:1px solid var(--studio-line);border-radius:24px!important;background:var(--studio-card)!important;box-shadow:0 16px 80px #2c21430a!important}.fi-simple-page{position:relative;padding-inline-start:51%}.studio-login-intro{position:absolute;inset-inline-start:0;top:0;bottom:0;width:44%;display:flex;flex-direction:column;align-items:flex-start;padding:12px 24px 10px 0;border-inline-end:1px solid var(--studio-line)}[dir=rtl] .studio-login-intro{padding:12px 0 10px 24px}.studio-login-intro h2{font-size:32px;font-weight:700;line-height:1.5;margin:16px 0 12px;max-width:290px}.studio-login-intro p{font-size:14px;color:var(--studio-muted);line-height:1.9;max-width:290px}.studio-login-intro small{display:flex;align-items:center;gap:8px;font-size:11px;color:var(--studio-muted);margin-top:auto}.studio-login-intro small svg{width:14px}.studio-login-art{height:150px;width:200px;position:relative;display:grid;place-items:center;margin:20px 0;color:#a48adc}.studio-login-art span{position:absolute;width:115px;height:115px;border:1px solid #a48adc55;border-radius:28px;transform:rotate(-15deg)}.studio-login-art span:nth-child(2){transform:rotate(15deg);background:#a48adc0a}.studio-login-art span:nth-child(3){transform:rotate(45deg);width:90px;height:90px;background:#a48adc13}.studio-login-art svg{position:relative;width:65px;height:65px}.fi-simple-header .studio-brand{margin-bottom:20px}.fi-simple-header-heading{font-size:23px!important}
a:focus-visible,button:focus-visible{outline:3px solid #b39ae8;outline-offset:3px}
@media(min-width:1600px){.fi-main{padding-inline:48px!important}.studio-welcome{padding:36px 42px}}
@media(max-width:1100px){.studio-grid{grid-template-columns:1fr}.studio-metrics{grid-template-columns:repeat(2,minmax(0,1fr))}.studio-orbit{width:135px;height:135px;margin:0}.studio-welcome{padding:26px}.studio-sidebar-footer{padding:10px}}
@media(max-width:700px){.fi-main{padding-inline:16px!important}.fi-page{padding-block:20px}.studio-welcome{padding:23px}.studio-welcome h2{font-size:23px}.studio-welcome p{font-size:12px}.studio-orbit{display:none}.studio-metrics{gap:10px}.studio-metric{padding:16px}.studio-metric-top{font-size:11px}.studio-metric strong{font-size:29px}.studio-icon{width:30px;height:30px}.studio-card-heading{padding:20px}.studio-context{font-size:10px}.studio-page-footer{gap:20px;line-height:1.6}.fi-simple-main{padding:28px!important;max-width:440px!important}.fi-simple-page{padding-inline-start:0}.studio-login-intro{position:static;width:auto;border:0;padding:0!important;margin-bottom:24px}.studio-login-intro h2{font-size:24px;margin:8px 0}.studio-login-intro p,.studio-login-art,.studio-login-intro small{display:none}.fi-simple-main-ctn{padding:24px 16px!important}.studio-card-heading h3{font-size:16px}}
@media(prefers-reduced-motion:reduce){*{transition:none!important;scroll-behavior:auto!important}}
.studio-login-languages{display:flex;gap:16px;font-size:12px;color:var(--studio-accent);margin:8px 0 18px}
.studio-locales{display:flex;flex-shrink:0;gap:4px;align-items:center;margin-inline:8px;white-space:nowrap}.studio-locales a{font-size:11px;color:var(--studio-muted);padding:5px;border-radius:5px}.studio-locales a[aria-current]{color:var(--studio-accent);background:var(--studio-soft);font-weight:700}
@media(max-width:700px){.studio-locales{gap:1px;margin-inline:3px}.studio-locales a{padding:4px;font-size:10px}.fi-global-search-field{max-width:145px}}
</style>
